insert into public.productos as p (id, nombre, precio, categorias, nuevo, activo, descripcion, imagenes, variantes, stock, orden, creado)
select
  e->>'id',
  e->>'nombre',
  (e->>'precio')::numeric,
  array(select jsonb_array_elements_text(e->'categorias')),
  (e->>'nuevo')::boolean,
  (e->>'activo')::boolean,
  coalesce(e->>'descripcion', ''),
  array(select jsonb_array_elements_text(e->'imagenes')),
  e->'variantes',
  (e->>'stock')::integer,
  0,
  case when (e->>'ts')::bigint > 0 then to_timestamp((e->>'ts')::bigint / 1000.0) else now() end
