-- 1) Tabla de pedidos (el número sigue después de tu nota #1001 de Shopify)
create table if not exists public.pedidos (
  numero            bigint generated by default as identity (start with 1002) primary key,
  creado            timestamptz not null default now(),
  estado            text not null default 'nuevo',      -- nuevo, confirmado, pagado, entregado, cancelado
  origen            text not null default 'web',        -- web o manual
  cliente           text not null default '',
  telefono          text not null default '',
  ciudad            text not null default '',
  direccion         text not null default '',
  entrega           text not null default '',
  nota              text not null default '',
  items             jsonb not null default '[]',        -- [{id, nombre, variante, cant, precio, desc, desc_nota}]
  envio             numeric(10,2) not null default 0,
  pagado            numeric(10,2) not null default 0,
  stock_descontado  boolean not null default false
);

alter table public.pedidos enable row level security;

-- Solo tú (administradora) puedes ver, crear a mano, editar y borrar pedidos
revoke all on public.pedidos from anon;
grant select, insert, update, delete on public.pedidos to authenticated;
grant usage, select on sequence public.pedidos_numero_seq to authenticated;

drop policy if exists "admin ve pedidos" on public.pedidos;
create policy "admin ve pedidos" on public.pedidos for select to authenticated using (public.es_admin());
drop policy if exists "admin crea pedidos" on public.pedidos;
create policy "admin crea pedidos" on public.pedidos for insert to authenticated with check (public.es_admin());
drop policy if exists "admin edita pedidos" on public.pedidos;
create policy "admin edita pedidos" on public.pedidos for update to authenticated using (public.es_admin()) with check (public.es_admin());
drop policy if exists "admin borra pedidos" on public.pedidos;
create policy "admin borra pedidos" on public.pedidos for delete to authenticated using (public.es_admin());

-- 2) Los clientes crean pedidos desde la tienda.
--    Los precios se toman de la base de datos (nadie puede cambiarlos desde el navegador).
create or replace function public.crear_pedido(p jsonb)
returns bigint
language plpgsql security definer set search_path = public as $$
declare
  it jsonb; prod record; items jsonb := '[]'; n int := 0; cant int; vari text; num bigint;
begin
  if jsonb_typeof(p->'items') <> 'array' or jsonb_array_length(p->'items') = 0 or jsonb_array_length(p->'items') > 60 then
    raise exception 'Pedido vacío o demasiado grande';
  end if;
  for it in select * from jsonb_array_elements(p->'items') loop
    select * into prod from productos where id = it->>'id' and activo;
    if not found then continue; end if;
    cant := least(greatest(coalesce((it->>'cant')::int, 1), 1), 99);
    vari := nullif(left(coalesce(it->>'variante', ''), 120), '');
    if jsonb_array_length(prod.variantes) > 0 and not exists (
         select 1 from jsonb_array_elements(prod.variantes) v where v->>'nombre' = vari) then
      continue;
    end if;
    if jsonb_array_length(prod.variantes) = 0 then vari := null; end if;
    items := items || jsonb_build_object('id', prod.id, 'nombre', prod.nombre, 'variante', vari,
                                         'cant', cant, 'precio', prod.precio, 'desc', 0, 'desc_nota', '');
    n := n + 1;
  end loop;
  if n = 0 then raise exception 'Ningún producto válido'; end if;
  insert into pedidos (cliente, telefono, ciudad, direccion, entrega, nota, items)
  values (left(coalesce(p->>'cliente', ''), 120), left(coalesce(p->>'telefono', ''), 40),
          left(coalesce(p->>'ciudad', ''), 80), left(coalesce(p->>'direccion', ''), 250),
          left(coalesce(p->>'entrega', ''), 120), left(coalesce(p->>'nota', ''), 500), items)
  returning numero into num;
  return num;
end $$;

revoke all on function public.crear_pedido(jsonb) from public;
grant execute on function public.crear_pedido(jsonb) to anon, authenticated;

-- 3) Descontar (signo = 1) o devolver (signo = -1) el stock de un pedido. Solo administradora.
--    Si no alcanza el stock, no descuenta nada y avisa qué falta.
create or replace function public.mover_stock(num bigint, signo int)
returns void
language plpgsql security definer set search_path = public as $$
declare ped record; it jsonb; prod record; disp int; faltan text := '';
begin
  if not public.es_admin() then raise exception 'No autorizado'; end if;
  if signo not in (1, -1) then raise exception 'Signo inválido'; end if;
  select * into ped from pedidos where numero = num for update;
  if not found then raise exception 'Pedido no existe'; end if;
  if signo = 1 and ped.stock_descontado then return; end if;
  if signo = -1 and not ped.stock_descontado then return; end if;

  if signo = 1 then
    for it in select * from jsonb_array_elements(ped.items) loop
      select * into prod from productos where id = it->>'id' for update;
      if not found then continue; end if;
      if jsonb_array_length(prod.variantes) > 0 then
        select coalesce((v->>'stock')::int, 0) into disp from jsonb_array_elements(prod.variantes) v where v->>'nombre' = it->>'variante';
      else
        disp := coalesce(prod.stock, 0);
      end if;
      if coalesce(disp, 0) < (it->>'cant')::int then
        faltan := faltan || format(E'\n• %s%s: hay %s, pide %s', prod.nombre,
                  coalesce(' (' || (it->>'variante') || ')', ''), coalesce(disp, 0), it->>'cant');
      end if;
    end loop;
    if faltan <> '' then raise exception 'No alcanza el stock:%', faltan; end if;
  end if;

  for it in select * from jsonb_array_elements(ped.items) loop
    update productos pr set
      stock = case when jsonb_array_length(pr.variantes) = 0 then coalesce(pr.stock, 0) - signo * (it->>'cant')::int else pr.stock end,
      variantes = case when jsonb_array_length(pr.variantes) = 0 then pr.variantes else (
        select jsonb_agg(case when v->>'nombre' = it->>'variante'
                              then jsonb_set(v, '{stock}', to_jsonb(coalesce((v->>'stock')::int, 0) - signo * (it->>'cant')::int))
                              else v end order by o)
        from jsonb_array_elements(pr.variantes) with ordinality t(v, o)) end
    where pr.id = it->>'id';
  end loop;

  update pedidos set stock_descontado = (signo = 1) where numero = num;
end $$;

revoke all on function public.mover_stock(bigint, int) from public;
grant execute on function public.mover_stock(bigint, int) to authenticated;


