-- 2) Carpeta PRIVADA para comprobantes: los clientes pueden subir, solo tú puedes verlos
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('comprobantes', 'comprobantes', false, 6291456,
        array['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit,
                               allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "clientes suben comprobantes" on storage.objects;
create policy "clientes suben comprobantes" on storage.objects
